from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENT = Decimal("0.01")
_ZERO = Decimal("0")


def _nvl(value: Any, default: Any = 0) -> Any:
    if value is None:
        return default
    if isinstance(value, str) and value.strip() == "":
        return default
    return value


def _decimal(value: Any, default: Any = 0) -> Decimal:
    value = _nvl(value, default)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(str(value))
    try:
        return Decimal(value)
    except (InvalidOperation, TypeError, ValueError):
        return Decimal(str(default))


def _money(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    if order["STAT_CD"] != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated = dict(order)

    if new_status == "X":
        updated["STAT_CD"] = "X"
        return updated, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return updated, [], []

    raise BusinessRuleViolation(
        "E5003",
        "Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    status = order["STAT_CD"]
    copied_order = dict(order)
    copied_lines = [dict(line) for line in lines]

    if status in ("I", "X"):
        return copied_order, copied_lines, []

    total = _ZERO

    for line in copied_lines:
        if line.get("DEL_FLG", "") == "Y":
            continue

        quantity = _decimal(line.get("QTY"))
        unit_price = _decimal(line.get("UNIT_PRC"))
        extension = _money(quantity * unit_price)
        line["EXT_AMT"] = float(extension)
        total += extension

    discount = _decimal(copied_order.get("DISC_PCT"))
    recomputed_total = _money(total * (Decimal("100") - discount) / Decimal("100"))

    stored_total = _decimal(copied_order.get("TOT_AMT"))
    audits = [] if stored_total == recomputed_total else ["ORD_RETOTAL"]

    copied_order["TOT_AMT"] = float(recomputed_total)
    return copied_order, copied_lines, audits
